-- P15 franchise finance: versioned basis, exact P&L, immutable allocations and distributions.

create table public.franchise_finance_rule_versions(
 id uuid primary key default extensions.gen_random_uuid(),franchise_type text not null check(franchise_type in('IT','STANDARD')),version integer not null check(version>0),operator_code text not null,entry_fee_required boolean not null,franchisee_share_bps integer not null check(franchisee_share_bps between 0 and 10000),neoxa_share_bps integer not null check(neoxa_share_bps between 0 and 10000),asma_matricia_share_bps integer not null check(asma_matricia_share_bps between 0 and 10000),distribution_basis text not null check(distribution_basis='DISTRIBUTABLE_PROFIT'),formula_snapshot jsonb not null check(jsonb_typeof(formula_snapshot)='object'and formula_snapshot?&array['revenue_categories','deduction_categories','vat_treatment','shared_central_cost_policy','rounding_policy']),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),effective_from date not null,effective_to date,status text not null check(status in('ACTIVE','RETIRED')),approval_reason text not null check(length(btrim(approval_reason))between 10 and 1000),approved_by uuid references auth.users(id),approved_at timestamptz not null default clock_timestamp(),unique(franchise_type,version),check(franchisee_share_bps+neoxa_share_bps+asma_matricia_share_bps=10000),check(effective_to is null or effective_to>=effective_from),check(franchise_type<>'IT'or(operator_code='HATIM_AHMITECH'and entry_fee_required=false and franchisee_share_bps=5000 and neoxa_share_bps=5000 and asma_matricia_share_bps=0)),check(formula_snapshot->>'vat_treatment'='EXCLUDED_FROM_REVENUE_AND_PROFIT'),check(formula_snapshot->>'rounding_policy'='LAST_BENEFICIARY_REMAINDER')
);

create table public.franchise_pnl_books(
 id uuid primary key default extensions.gen_random_uuid(),library_id uuid not null references public.catalog_libraries(id)on delete restrict,franchise_organization_id uuid not null references public.organizations(id)on delete restrict,franchise_type text not null check(franchise_type in('IT','STANDARD')),operator_code text not null,currency char(3)not null check(currency~'^[A-Z]{3}$'),opened_under_rule_version_id uuid not null references public.franchise_finance_rule_versions(id)on delete restrict,status text not null default'OPEN'check(status in('OPEN','CLOSED')),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(library_id,franchise_organization_id),unique(id,franchise_organization_id),check(franchise_type<>'IT'or operator_code='HATIM_AHMITECH')
);

create table public.franchise_entry_fee_schedules(
 id uuid primary key default extensions.gen_random_uuid(),book_id uuid not null unique references public.franchise_pnl_books(id)on delete restrict,rule_version_id uuid not null references public.franchise_finance_rule_versions(id)on delete restrict,mode text not null check(mode in('EXEMPT','UPFRONT','INSTALLMENT','REVENUE_WITHHOLDING')),principal_minor bigint not null check(principal_minor>=0),deposit_minor bigint not null default 0 check(deposit_minor>=0),withholding_bps integer check(withholding_bps between 1 and 10000),installment_count integer check(installment_count between 1 and 6),starts_on date not null,due_on date not null,terms_snapshot jsonb not null check(jsonb_typeof(terms_snapshot)='object'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),check(due_on>=starts_on and due_on<=starts_on+interval'6 months'),check(deposit_minor<=principal_minor),check((mode='EXEMPT'and principal_minor=0 and deposit_minor=0 and withholding_bps is null and installment_count is null)or(mode='UPFRONT'and principal_minor>0 and deposit_minor=principal_minor and withholding_bps is null and installment_count is null)or(mode='INSTALLMENT'and principal_minor>0 and installment_count is not null and withholding_bps is null)or(mode='REVENUE_WITHHOLDING'and principal_minor>0 and withholding_bps is not null))
);

create table public.franchise_entry_fee_ledger_entries(
 id bigint generated always as identity primary key,schedule_id uuid not null references public.franchise_entry_fee_schedules(id)on delete restrict,entry_type text not null check(entry_type in('DUE','PAYMENT','WITHHOLDING','REVERSAL')),amount_minor bigint not null check(amount_minor<>0),financial_journal_id uuid references public.financial_journals(id)on delete restrict,reference_type text not null,reference_id text not null,proof_hash text check(proof_hash~'^[0-9a-f]{64}$'),correlation_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(schedule_id,entry_type,reference_type,reference_id),check((entry_type='DUE'and amount_minor>0)or(entry_type in('PAYMENT','WITHHOLDING')and amount_minor<0)or entry_type='REVERSAL')
);

create table public.franchise_pnl_entries(
 id uuid primary key default extensions.gen_random_uuid(),book_id uuid not null references public.franchise_pnl_books(id)on delete restrict,effect_type text not null check(effect_type in('REVENUE','COST','REVERSAL_REVENUE','REVERSAL_COST')),category text not null check(category in('COLLECTED_NET_REVENUE','REFUND_CREDIT_NOTE','PROVIDER_FULFILLMENT_COST','VOLUME_CONTRACT_COST','PAYMENT_FEE','DIRECT_MARKETING_COST','APPROVED_DIRECT_OTHER_COST','APPROVED_SHARED_CENTRAL_COST')),amount_minor bigint not null check(amount_minor>0),currency char(3)not null check(currency~'^[A-Z]{3}$'),financial_journal_id uuid not null references public.financial_journals(id)on delete restrict,source_type text not null,source_id text not null,effective_on date not null,reason text not null check(length(btrim(reason))between 3 and 1000),reverses_entry_id uuid references public.franchise_pnl_entries(id)on delete restrict,correlation_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(book_id,source_type,source_id,effect_type),check((effect_type in('REVENUE','COST')and reverses_entry_id is null)or(effect_type in('REVERSAL_REVENUE','REVERSAL_COST')and reverses_entry_id is not null)),check((category='COLLECTED_NET_REVENUE'and effect_type in('REVENUE','REVERSAL_REVENUE'))or(category<>'COLLECTED_NET_REVENUE'and effect_type in('COST','REVERSAL_COST')))
);

create table public.franchise_profit_closure_versions(
 id uuid primary key default extensions.gen_random_uuid(),book_id uuid not null references public.franchise_pnl_books(id)on delete restrict,period_start date not null,period_end date not null,version integer not null check(version>0),supersedes_closure_id uuid references public.franchise_profit_closure_versions(id)on delete restrict,rule_version_id uuid not null references public.franchise_finance_rule_versions(id)on delete restrict,rule_snapshot jsonb not null check(jsonb_typeof(rule_snapshot)='object'),formula_snapshot jsonb not null check(jsonb_typeof(formula_snapshot)='object'),entry_cutoff_at timestamptz not null,gross_revenue_ex_tax_minor bigint not null,costs_and_refunds_minor bigint not null check(costs_and_refunds_minor>=0),distributable_profit_minor bigint not null,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),closed_by uuid not null references auth.users(id),closed_at timestamptz not null default clock_timestamp(),unique(book_id,period_start,period_end,version),check(period_end>=period_start and period_end<period_start+interval'1 year')
);

create table public.franchise_profit_allocations(
 id uuid primary key default extensions.gen_random_uuid(),closure_version_id uuid not null references public.franchise_profit_closure_versions(id)on delete restrict,beneficiary_code text not null check(beneficiary_code in('HATIM_AHMITECH','FRANCHISEE','NEOXA_JALIL','ASMA_MATRICIA')),share_bps integer not null check(share_bps between 0 and 10000),amount_minor bigint not null check(amount_minor>=0),currency char(3)not null check(currency~'^[A-Z]{3}$'),rounding_adjustment_minor integer not null default 0 check(abs(rounding_adjustment_minor)<=2),rights_snapshot jsonb not null check(jsonb_typeof(rights_snapshot)='object'),created_at timestamptz not null default clock_timestamp(),unique(closure_version_id,beneficiary_code)
);

create table public.franchise_distribution_ledger_entries(
 id bigint generated always as identity primary key,book_id uuid not null references public.franchise_pnl_books(id)on delete restrict,closure_version_id uuid references public.franchise_profit_closure_versions(id)on delete restrict,allocation_id uuid references public.franchise_profit_allocations(id)on delete restrict,beneficiary_code text not null check(beneficiary_code in('HATIM_AHMITECH','FRANCHISEE','NEOXA_JALIL','ASMA_MATRICIA')),entry_type text not null check(entry_type in('ACCRUAL','ADJUSTMENT','PAYOUT','REVERSAL')),amount_minor bigint not null check(amount_minor<>0),currency char(3)not null check(currency~'^[A-Z]{3}$'),financial_journal_id uuid references public.financial_journals(id)on delete restrict,reference_type text not null,reference_id text not null,proof_hash text check(proof_hash~'^[0-9a-f]{64}$'),correlation_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(book_id,beneficiary_code,entry_type,reference_type,reference_id),check((entry_type='ACCRUAL'and amount_minor>0)or(entry_type='PAYOUT'and amount_minor<0)or entry_type in('ADJUSTMENT','REVERSAL'))
);

create function private.franchise_book_access(p_book uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select exists(select 1 from public.franchise_pnl_books b where b.id=p_book and private.has_org_role(b.franchise_organization_id,array['FRANCHISE_OWNER','FRANCHISE_MANAGER','FRANCHISE_ACCOUNTING','FRANCHISE_VIEWER'],p_actor))or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','FINANCE_MANAGER','READ_ONLY_AUDITOR'],p_actor)$$;
create function private.prevent_franchise_finance_change()returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception 'IMMUTABLE_FRANCHISE_FINANCE_RECORD'using errcode='55000';end$$;
create function private.assert_franchise_allocation_total()returns trigger language plpgsql set search_path=pg_catalog,public as $$declare cid uuid:=coalesce(new.closure_version_id,old.closure_version_id);expected bigint;actual bigint;items integer;begin select greatest(distributable_profit_minor,0)into expected from public.franchise_profit_closure_versions where id=cid;select count(*),coalesce(sum(amount_minor),0)into items,actual from public.franchise_profit_allocations where closure_version_id=cid;if items<>3 or actual<>expected then raise exception 'UNBALANCED_FRANCHISE_ALLOCATION'using errcode='23514';end if;return null;end$$;

create function public.create_franchise_finance_rule(p_audit_organization_id uuid,p_franchise_type text,p_operator_code text,p_entry_fee_required boolean,p_franchisee_share_bps integer,p_neoxa_share_bps integer,p_asma_share_bps integer,p_formula_snapshot jsonb,p_effective_from date,p_effective_to date,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();v integer;h text;r jsonb;id uuid;org uuid;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_RULE_DENIED'using errcode='42501';end if;if p_franchise_type not in('IT','STANDARD')or p_franchisee_share_bps+p_neoxa_share_bps+p_asma_share_bps<>10000 or least(p_franchisee_share_bps,p_neoxa_share_bps,p_asma_share_bps)<0 or greatest(p_franchisee_share_bps,p_neoxa_share_bps,p_asma_share_bps)>10000 or jsonb_typeof(p_formula_snapshot)<>'object'or not(p_formula_snapshot?&array['revenue_categories','deduction_categories','vat_treatment','shared_central_cost_policy','rounding_policy'])or p_formula_snapshot->>'vat_treatment'<>'EXCLUDED_FROM_REVENUE_AND_PROFIT'or p_formula_snapshot->>'rounding_policy'<>'LAST_BENEFICIARY_REMAINDER'or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 or p_effective_to<p_effective_from or(p_franchise_type='IT'and(p_operator_code<>'HATIM_AHMITECH'or p_entry_fee_required or p_franchisee_share_bps<>5000 or p_neoxa_share_bps<>5000 or p_asma_share_bps<>0))then raise exception 'INVALID_FRANCHISE_RULE'using errcode='22023';end if;if not exists(select 1 from public.organizations where id=p_audit_organization_id and status='ACTIVE')then raise exception 'AUDIT_ORGANIZATION_REQUIRED'using errcode='23514';end if;org:=p_audit_organization_id;h:=private.canonical_request_hash(jsonb_build_object('audit_organization_id',org,'type',p_franchise_type,'operator',p_operator_code,'fee_required',p_entry_fee_required,'shares',jsonb_build_array(p_franchisee_share_bps,p_neoxa_share_bps,p_asma_share_bps),'formula',p_formula_snapshot,'from',p_effective_from,'until',p_effective_to));r:=private.begin_contract_command(org,'franchise.rule.create.'||p_franchise_type,p_idempotency_key,h,a);if r is not null then return r;end if;select coalesce(max(version),0)+1 into v from public.franchise_finance_rule_versions where franchise_type=p_franchise_type;insert into public.franchise_finance_rule_versions(franchise_type,version,operator_code,entry_fee_required,franchisee_share_bps,neoxa_share_bps,asma_matricia_share_bps,distribution_basis,formula_snapshot,content_hash,effective_from,effective_to,status,approval_reason,approved_by)values(p_franchise_type,v,p_operator_code,p_entry_fee_required,p_franchisee_share_bps,p_neoxa_share_bps,p_asma_share_bps,'DISTRIBUTABLE_PROFIT',p_formula_snapshot,h,p_effective_from,p_effective_to,'ACTIVE',p_reason,a)returning id into id;r:=jsonb_build_object('outcome','FRANCHISE_RULE_CREATED','rule_version_id',id,'version',v,'content_hash',h);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','franchise.rule.created','franchise_finance_rule',id::text,p_correlation_id,jsonb_build_object('franchise_type',p_franchise_type,'version',v),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'franchise_finance_rule',id::text,'FranchiseFinanceRuleCreatedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(org,'franchise.rule.create.'||p_franchise_type,p_idempotency_key,r);return r;end$$;

create function public.open_franchise_pnl_book(p_library_id uuid,p_franchise_organization_id uuid,p_franchise_type text,p_operator_code text,p_currency text,p_rule_version_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();v public.franchise_finance_rule_versions%rowtype;h text;r jsonb;b uuid;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_BOOK_DENIED'using errcode='42501';end if;select * into v from public.franchise_finance_rule_versions where id=p_rule_version_id and status='ACTIVE';if not found or v.franchise_type<>p_franchise_type or v.operator_code<>p_operator_code or p_currency!~'^[A-Z]{3}$'or(p_franchise_type='IT'and p_operator_code<>'HATIM_AHMITECH')or not exists(select 1 from public.catalog_libraries where id=p_library_id)or not exists(select 1 from public.organizations where id=p_franchise_organization_id and status='ACTIVE')then raise exception 'INVALID_FRANCHISE_BOOK'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('library',p_library_id,'organization',p_franchise_organization_id,'type',p_franchise_type,'operator',p_operator_code,'currency',p_currency,'rule',p_rule_version_id));r:=private.begin_contract_command(p_franchise_organization_id,'franchise.book.open',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_pnl_books(library_id,franchise_organization_id,franchise_type,operator_code,currency,opened_under_rule_version_id,created_by)values(p_library_id,p_franchise_organization_id,p_franchise_type,p_operator_code,p_currency,p_rule_version_id,a)returning id into b;r:=jsonb_build_object('outcome','FRANCHISE_PNL_BOOK_OPENED','book_id',b);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_franchise_organization_id,a,'USER','franchise.pnl_book.opened','franchise_pnl_book',b::text,p_correlation_id,jsonb_build_object('library_id',p_library_id,'rule_version_id',p_rule_version_id),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_franchise_organization_id,'franchise_pnl_book',b::text,'FranchisePnlBookOpenedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_franchise_organization_id,'franchise.book.open',p_idempotency_key,r);return r;end$$;

create function public.create_franchise_entry_fee_schedule(p_book_id uuid,p_mode text,p_principal_minor bigint,p_deposit_minor bigint,p_withholding_bps integer,p_installment_count integer,p_starts_on date,p_due_on date,p_terms_snapshot jsonb,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();b public.franchise_pnl_books%rowtype;v public.franchise_finance_rule_versions%rowtype;h text;r jsonb;s uuid;begin select * into b from public.franchise_pnl_books where id=p_book_id;select * into v from public.franchise_finance_rule_versions where id=b.opened_under_rule_version_id;if a is null or not found or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'ENTRY_FEE_SCHEDULE_DENIED'using errcode='42501';end if;if jsonb_typeof(p_terms_snapshot)<>'object'or p_due_on<p_starts_on or p_due_on>p_starts_on+interval'6 months'or(b.franchise_type='IT'and(p_mode<>'EXEMPT'or p_principal_minor<>0 or p_deposit_minor<>0 or p_withholding_bps is not null or p_installment_count is not null or v.entry_fee_required))or(b.franchise_type='STANDARD'and(p_mode='EXEMPT'or p_principal_minor<=0))then raise exception 'INVALID_ENTRY_FEE_SCHEDULE'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('book',b.id,'mode',p_mode,'principal',p_principal_minor,'deposit',p_deposit_minor,'withholding_bps',p_withholding_bps,'installments',p_installment_count,'starts',p_starts_on,'due',p_due_on,'terms',p_terms_snapshot));r:=private.begin_contract_command(b.franchise_organization_id,'franchise.entry_fee.schedule',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_entry_fee_schedules(book_id,rule_version_id,mode,principal_minor,deposit_minor,withholding_bps,installment_count,starts_on,due_on,terms_snapshot,content_hash,created_by)values(b.id,v.id,p_mode,p_principal_minor,p_deposit_minor,p_withholding_bps,p_installment_count,p_starts_on,p_due_on,p_terms_snapshot,h,a)returning id into s;if p_principal_minor>0 then insert into public.franchise_entry_fee_ledger_entries(schedule_id,entry_type,amount_minor,reference_type,reference_id,correlation_id,created_by)values(s,'DUE',p_principal_minor,'ENTRY_FEE_SCHEDULE',s::text,p_correlation_id,a);end if;r:=jsonb_build_object('outcome',case when b.franchise_type='IT'then'IT_ENTRY_FEE_EXEMPT'else'ENTRY_FEE_SCHEDULED'end,'schedule_id',s,'principal_minor',p_principal_minor);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(b.franchise_organization_id,a,'USER','franchise.entry_fee.scheduled','franchise_entry_fee_schedule',s::text,p_correlation_id,jsonb_build_object('mode',p_mode,'principal_minor',p_principal_minor),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(b.franchise_organization_id,'franchise_entry_fee_schedule',s::text,'FranchiseEntryFeeScheduledV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(b.franchise_organization_id,'franchise.entry_fee.schedule',p_idempotency_key,r);return r;end$$;

create function public.post_franchise_pnl_entry(p_book_id uuid,p_effect_type text,p_category text,p_amount_minor bigint,p_financial_journal_id uuid,p_source_type text,p_source_id text,p_effective_on date,p_reason text,p_reverses_entry_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();b public.franchise_pnl_books%rowtype;j public.financial_journals%rowtype;x public.franchise_pnl_entries%rowtype;h text;r jsonb;e uuid;begin select * into b from public.franchise_pnl_books where id=p_book_id;select * into j from public.financial_journals where id=p_financial_journal_id;if a is null or b.id is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_PNL_POST_DENIED'using errcode='42501';end if;if b.status<>'OPEN'or p_effect_type not in('REVENUE','COST','REVERSAL_REVENUE','REVERSAL_COST')or p_category not in('COLLECTED_NET_REVENUE','REFUND_CREDIT_NOTE','PROVIDER_FULFILLMENT_COST','VOLUME_CONTRACT_COST','PAYMENT_FEE','DIRECT_MARKETING_COST','APPROVED_DIRECT_OTHER_COST','APPROVED_SHARED_CENTRAL_COST')or p_amount_minor<=0 or j.id is null or j.organization_id<>b.franchise_organization_id or j.currency<>b.currency or j.status<>'POSTED'or length(btrim(coalesce(p_reason,'')))not between 3 and 1000 then raise exception 'INVALID_FRANCHISE_PNL_ENTRY'using errcode='22023';end if;if p_effect_type in('REVERSAL_REVENUE','REVERSAL_COST')then select * into x from public.franchise_pnl_entries where id=p_reverses_entry_id and book_id=b.id;if not found or x.amount_minor<>p_amount_minor or(p_effect_type='REVERSAL_REVENUE'and x.effect_type<>'REVENUE')or(p_effect_type='REVERSAL_COST'and x.effect_type<>'COST')or exists(select 1 from public.franchise_pnl_entries where reverses_entry_id=x.id)then raise exception 'INVALID_PNL_REVERSAL'using errcode='22023';end if;elsif p_reverses_entry_id is not null then raise exception 'INVALID_PNL_REVERSAL'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('book',b.id,'effect',p_effect_type,'category',p_category,'amount',p_amount_minor,'journal',j.id,'source_type',p_source_type,'source_id',p_source_id,'effective_on',p_effective_on,'reason',p_reason,'reverses',p_reverses_entry_id));r:=private.begin_contract_command(b.franchise_organization_id,'franchise.pnl.post.'||b.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_pnl_entries(book_id,effect_type,category,amount_minor,currency,financial_journal_id,source_type,source_id,effective_on,reason,reverses_entry_id,correlation_id,created_by)values(b.id,p_effect_type,p_category,p_amount_minor,b.currency,j.id,p_source_type,p_source_id,p_effective_on,p_reason,p_reverses_entry_id,p_correlation_id,a)returning id into e;r:=jsonb_build_object('outcome','FRANCHISE_PNL_ENTRY_POSTED','entry_id',e,'book_id',b.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(b.franchise_organization_id,a,'USER','franchise.pnl_entry.posted','franchise_pnl_entry',e::text,p_correlation_id,jsonb_build_object('category',p_category,'amount_minor',p_amount_minor,'effect_type',p_effect_type),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(b.franchise_organization_id,'franchise_pnl_book',b.id::text,'FranchisePnlEntryPostedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(b.franchise_organization_id,'franchise.pnl.post.'||b.id::text,p_idempotency_key,r);return r;end$$;

create function public.close_franchise_profit_period(p_book_id uuid,p_period_start date,p_period_end date,p_rule_version_id uuid,p_entry_cutoff_at timestamptz,p_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();b public.franchise_pnl_books%rowtype;rv public.franchise_finance_rule_versions%rowtype;prior public.franchise_profit_closure_versions%rowtype;h text;r jsonb;c uuid;ver integer;revenue bigint;costs bigint;profit bigint;dist bigint;fa bigint;na bigint;aa bigint;rem bigint;benef text;alloc uuid;oldamt bigint;begin select * into b from public.franchise_pnl_books where id=p_book_id;select * into rv from public.franchise_finance_rule_versions where id=p_rule_version_id;if a is null or b.id is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_CLOSE_DENIED'using errcode='42501';end if;if b.status<>'OPEN'or rv.id is null or rv.status<>'ACTIVE'or rv.franchise_type<>b.franchise_type or p_period_start<rv.effective_from or(rv.effective_to is not null and p_period_end>rv.effective_to)or p_period_end<p_period_start or p_period_end>=p_period_start+interval'1 year'or p_entry_cutoff_at>clock_timestamp()or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception 'INVALID_FRANCHISE_CLOSURE'using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended(b.id::text||':'||p_period_start::text||':'||p_period_end::text,0));select * into prior from public.franchise_profit_closure_versions where book_id=b.id and period_start=p_period_start and period_end=p_period_end order by version desc limit 1;ver:=coalesce(prior.version,0)+1;select coalesce(sum(case when effect_type='REVENUE'then amount_minor when effect_type='REVERSAL_REVENUE'then-amount_minor else 0 end),0),coalesce(sum(case when effect_type='COST'then amount_minor when effect_type='REVERSAL_COST'then-amount_minor else 0 end),0)into revenue,costs from public.franchise_pnl_entries where book_id=b.id and effective_on between p_period_start and p_period_end and created_at<=p_entry_cutoff_at;if costs<0 then raise exception 'NEGATIVE_NET_COSTS_REQUIRE_REVIEW'using errcode='23514';end if;profit:=revenue-costs;h:=private.canonical_request_hash(jsonb_build_object('book',b.id,'period_start',p_period_start,'period_end',p_period_end,'version',ver,'rule',to_jsonb(rv),'cutoff',p_entry_cutoff_at,'revenue',revenue,'costs',costs,'profit',profit,'reason',p_reason));r:=private.begin_contract_command(b.franchise_organization_id,'franchise.pnl.close.'||b.id::text||'.'||p_period_start::text||'.'||p_period_end::text,p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_profit_closure_versions(book_id,period_start,period_end,version,supersedes_closure_id,rule_version_id,rule_snapshot,formula_snapshot,entry_cutoff_at,gross_revenue_ex_tax_minor,costs_and_refunds_minor,distributable_profit_minor,content_hash,closed_by)values(b.id,p_period_start,p_period_end,ver,prior.id,rv.id,to_jsonb(rv)-array['id','approved_by'],rv.formula_snapshot,p_entry_cutoff_at,revenue,costs,profit,h,a)returning id into c;dist:=greatest(profit,0);fa:=dist*rv.franchisee_share_bps/10000;na:=dist*rv.neoxa_share_bps/10000;aa:=dist*rv.asma_matricia_share_bps/10000;rem:=dist-fa-na-aa;if b.franchise_type='IT'then na:=na+rem;else aa:=aa+rem;end if;for benef in select * from unnest(case when b.franchise_type='IT'then array['HATIM_AHMITECH','NEOXA_JALIL','ASMA_MATRICIA']else array['FRANCHISEE','NEOXA_JALIL','ASMA_MATRICIA']end)loop insert into public.franchise_profit_allocations(closure_version_id,beneficiary_code,share_bps,amount_minor,currency,rounding_adjustment_minor,rights_snapshot)values(c,benef,case when benef in('HATIM_AHMITECH','FRANCHISEE')then rv.franchisee_share_bps when benef='NEOXA_JALIL'then rv.neoxa_share_bps else rv.asma_matricia_share_bps end,case when benef in('HATIM_AHMITECH','FRANCHISEE')then fa when benef='NEOXA_JALIL'then na else aa end,b.currency,case when(b.franchise_type='IT'and benef='NEOXA_JALIL')or(b.franchise_type='STANDARD'and benef='ASMA_MATRICIA')then rem else 0 end,jsonb_build_object('rule_version_id',rv.id,'rule_hash',rv.content_hash,'operator_code',rv.operator_code,'distribution_basis',rv.distribution_basis))returning id into alloc;select coalesce(pa.amount_minor,0)into oldamt from public.franchise_profit_allocations pa where pa.closure_version_id=prior.id and pa.beneficiary_code=benef;if not found then oldamt:=0;end if;if(case when benef in('HATIM_AHMITECH','FRANCHISEE')then fa when benef='NEOXA_JALIL'then na else aa end)-oldamt<>0 then insert into public.franchise_distribution_ledger_entries(book_id,closure_version_id,allocation_id,beneficiary_code,entry_type,amount_minor,currency,reference_type,reference_id,correlation_id,created_by)values(b.id,c,alloc,benef,case when prior.id is null then'ACCRUAL'else'ADJUSTMENT'end,(case when benef in('HATIM_AHMITECH','FRANCHISEE')then fa when benef='NEOXA_JALIL'then na else aa end)-oldamt,b.currency,'PROFIT_CLOSURE',c::text,p_correlation_id,a);end if;end loop;r:=jsonb_build_object('outcome','FRANCHISE_PROFIT_CLOSED','closure_version_id',c,'version',ver,'gross_revenue_ex_tax_minor',revenue,'costs_and_refunds_minor',costs,'distributable_profit_minor',profit);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(b.franchise_organization_id,a,'USER','franchise.profit.closed','franchise_profit_closure',c::text,p_correlation_id,jsonb_build_object('version',ver,'rule_version_id',rv.id,'content_hash',h),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(b.franchise_organization_id,'franchise_profit_closure',c::text,'FranchiseProfitClosedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(b.franchise_organization_id,'franchise.pnl.close.'||b.id::text||'.'||p_period_start::text||'.'||p_period_end::text,p_idempotency_key,r);return r;end$$;

create function public.record_franchise_distribution_payout(p_book_id uuid,p_beneficiary_code text,p_amount_minor bigint,p_financial_journal_id uuid,p_reference text,p_proof_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();b public.franchise_pnl_books%rowtype;j public.financial_journals%rowtype;bal bigint;h text;r jsonb;e bigint;begin select * into b from public.franchise_pnl_books where id=p_book_id;select * into j from public.financial_journals where id=p_financial_journal_id;if a is null or b.id is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_PAYOUT_DENIED'using errcode='42501';end if;if p_beneficiary_code not in('HATIM_AHMITECH','FRANCHISEE','NEOXA_JALIL','ASMA_MATRICIA')or p_amount_minor<=0 or j.id is null or j.organization_id<>b.franchise_organization_id or j.currency<>b.currency or j.status<>'POSTED'or length(btrim(coalesce(p_reference,'')))<3 or p_proof_hash!~'^[0-9a-f]{64}$'then raise exception 'INVALID_FRANCHISE_PAYOUT'using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended(b.id::text||':'||p_beneficiary_code,0));select coalesce(sum(amount_minor),0)into bal from public.franchise_distribution_ledger_entries where book_id=b.id and beneficiary_code=p_beneficiary_code;if bal<p_amount_minor then raise exception 'INSUFFICIENT_DISTRIBUTABLE_BALANCE'using errcode='23514';end if;h:=private.canonical_request_hash(jsonb_build_object('book',b.id,'beneficiary',p_beneficiary_code,'amount',p_amount_minor,'journal',j.id,'reference',p_reference,'proof_hash',p_proof_hash));r:=private.begin_contract_command(b.franchise_organization_id,'franchise.distribution.payout.'||b.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_distribution_ledger_entries(book_id,beneficiary_code,entry_type,amount_minor,currency,financial_journal_id,reference_type,reference_id,proof_hash,correlation_id,created_by)values(b.id,p_beneficiary_code,'PAYOUT',-p_amount_minor,b.currency,j.id,'PAYOUT',p_reference,p_proof_hash,p_correlation_id,a)returning id into e;r:=jsonb_build_object('outcome','FRANCHISE_DISTRIBUTION_RECORDED','ledger_entry_id',e,'remaining_balance_minor',bal-p_amount_minor);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(b.franchise_organization_id,a,'USER','franchise.distribution.recorded','franchise_distribution_entry',e::text,p_correlation_id,jsonb_build_object('beneficiary_code',p_beneficiary_code,'amount_minor',p_amount_minor),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(b.franchise_organization_id,'franchise_pnl_book',b.id::text,'FranchiseDistributionRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(b.franchise_organization_id,'franchise.distribution.payout.'||b.id::text,p_idempotency_key,r);return r;end$$;

create trigger franchise_rules_immutable before update or delete on public.franchise_finance_rule_versions for each row execute function private.prevent_franchise_finance_change();create trigger franchise_books_immutable before update or delete on public.franchise_pnl_books for each row execute function private.prevent_franchise_finance_change();create trigger franchise_fee_schedules_immutable before update or delete on public.franchise_entry_fee_schedules for each row execute function private.prevent_franchise_finance_change();create trigger franchise_fee_ledger_immutable before update or delete on public.franchise_entry_fee_ledger_entries for each row execute function private.prevent_franchise_finance_change();create trigger franchise_pnl_entries_immutable before update or delete on public.franchise_pnl_entries for each row execute function private.prevent_franchise_finance_change();create trigger franchise_closures_immutable before update or delete on public.franchise_profit_closure_versions for each row execute function private.prevent_franchise_finance_change();create trigger franchise_allocations_immutable before update or delete on public.franchise_profit_allocations for each row execute function private.prevent_franchise_finance_change();create trigger franchise_distribution_immutable before update or delete on public.franchise_distribution_ledger_entries for each row execute function private.prevent_franchise_finance_change();
create constraint trigger franchise_allocations_balanced after insert or update or delete on public.franchise_profit_allocations deferrable initially deferred for each row execute function private.assert_franchise_allocation_total();

alter table public.franchise_finance_rule_versions enable row level security;alter table public.franchise_pnl_books enable row level security;alter table public.franchise_entry_fee_schedules enable row level security;alter table public.franchise_entry_fee_ledger_entries enable row level security;alter table public.franchise_pnl_entries enable row level security;alter table public.franchise_profit_closure_versions enable row level security;alter table public.franchise_profit_allocations enable row level security;alter table public.franchise_distribution_ledger_entries enable row level security;
create policy franchise_rules_active_read on public.franchise_finance_rule_versions for select to authenticated using(status='ACTIVE'or private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER','READ_ONLY_AUDITOR']));create policy franchise_books_scoped_read on public.franchise_pnl_books for select to authenticated using(private.franchise_book_access(id));create policy franchise_fee_schedules_scoped_read on public.franchise_entry_fee_schedules for select to authenticated using(private.franchise_book_access(book_id));create policy franchise_fee_ledger_scoped_read on public.franchise_entry_fee_ledger_entries for select to authenticated using(private.franchise_book_access((select s.book_id from public.franchise_entry_fee_schedules s where s.id=schedule_id)));create policy franchise_pnl_entries_scoped_read on public.franchise_pnl_entries for select to authenticated using(private.franchise_book_access(book_id));create policy franchise_closures_scoped_read on public.franchise_profit_closure_versions for select to authenticated using(private.franchise_book_access(book_id));create policy franchise_allocations_scoped_read on public.franchise_profit_allocations for select to authenticated using(private.franchise_book_access((select c.book_id from public.franchise_profit_closure_versions c where c.id=closure_version_id)));create policy franchise_distribution_scoped_read on public.franchise_distribution_ledger_entries for select to authenticated using(private.franchise_book_access(book_id));
revoke all on public.franchise_finance_rule_versions,public.franchise_pnl_books,public.franchise_entry_fee_schedules,public.franchise_entry_fee_ledger_entries,public.franchise_pnl_entries,public.franchise_profit_closure_versions,public.franchise_profit_allocations,public.franchise_distribution_ledger_entries from public,anon,authenticated;grant select on public.franchise_finance_rule_versions,public.franchise_pnl_books,public.franchise_entry_fee_schedules,public.franchise_entry_fee_ledger_entries,public.franchise_pnl_entries,public.franchise_profit_closure_versions,public.franchise_profit_allocations,public.franchise_distribution_ledger_entries to authenticated;
revoke all on function private.franchise_book_access(uuid,uuid),private.prevent_franchise_finance_change(),private.assert_franchise_allocation_total()from public,anon,authenticated,service_role;revoke all on function public.create_franchise_finance_rule(uuid,text,text,boolean,integer,integer,integer,jsonb,date,date,text,text,uuid),public.open_franchise_pnl_book(uuid,uuid,text,text,text,uuid,text,uuid),public.create_franchise_entry_fee_schedule(uuid,text,bigint,bigint,integer,integer,date,date,jsonb,text,uuid),public.post_franchise_pnl_entry(uuid,text,text,bigint,uuid,text,text,date,text,uuid,text,uuid),public.close_franchise_profit_period(uuid,date,date,uuid,timestamptz,text,text,uuid),public.record_franchise_distribution_payout(uuid,text,bigint,uuid,text,text,text,uuid)from public,anon,authenticated,service_role;grant execute on function public.create_franchise_finance_rule(uuid,text,text,boolean,integer,integer,integer,jsonb,date,date,text,text,uuid),public.open_franchise_pnl_book(uuid,uuid,text,text,text,uuid,text,uuid),public.create_franchise_entry_fee_schedule(uuid,text,bigint,bigint,integer,integer,date,date,jsonb,text,uuid),public.post_franchise_pnl_entry(uuid,text,text,bigint,uuid,text,text,date,text,uuid,text,uuid),public.close_franchise_profit_period(uuid,date,date,uuid,timestamptz,text,text,uuid),public.record_franchise_distribution_payout(uuid,text,bigint,uuid,text,text,text,uuid)to authenticated;
create index franchise_rules_effective_idx on public.franchise_finance_rule_versions(franchise_type,status,effective_from,effective_to);create index franchise_books_org_idx on public.franchise_pnl_books(franchise_organization_id,status,library_id);create index franchise_fee_ledger_balance_idx on public.franchise_entry_fee_ledger_entries(schedule_id,id);create index franchise_pnl_period_idx on public.franchise_pnl_entries(book_id,effective_on,created_at);create index franchise_closures_latest_idx on public.franchise_profit_closure_versions(book_id,period_start,period_end,version desc);create index franchise_allocations_beneficiary_idx on public.franchise_profit_allocations(beneficiary_code,closure_version_id);create index franchise_distribution_balance_idx on public.franchise_distribution_ledger_entries(book_id,beneficiary_code,id);

insert into public.franchise_finance_rule_versions(franchise_type,version,operator_code,entry_fee_required,franchisee_share_bps,neoxa_share_bps,asma_matricia_share_bps,distribution_basis,formula_snapshot,content_hash,effective_from,status,approval_reason)values
('IT',1,'HATIM_AHMITECH',false,5000,5000,0,'DISTRIBUTABLE_PROFIT','{"revenue_categories":["COLLECTED_NET_REVENUE"],"deduction_categories":["REFUND_CREDIT_NOTE","PROVIDER_FULFILLMENT_COST","VOLUME_CONTRACT_COST","PAYMENT_FEE","DIRECT_MARKETING_COST","APPROVED_DIRECT_OTHER_COST","APPROVED_SHARED_CENTRAL_COST"],"vat_treatment":"EXCLUDED_FROM_REVENUE_AND_PROFIT","shared_central_cost_policy":"EXCLUDED_UNLESS_EXPLICITLY_APPROVED_AND_VERSIONED","rounding_policy":"LAST_BENEFICIARY_REMAINDER"}',private.canonical_request_hash('{"rule":"GOLD_MASTER_IT_V1"}'::jsonb),'2026-09-10','ACTIVE','Gold Master V4 FINAL — franchise IT Hatim Ahmitech, exemption et partage 50/50'),
('STANDARD',1,'FRANCHISEE',true,5000,2500,2500,'DISTRIBUTABLE_PROFIT','{"revenue_categories":["COLLECTED_NET_REVENUE"],"deduction_categories":["REFUND_CREDIT_NOTE","PROVIDER_FULFILLMENT_COST","VOLUME_CONTRACT_COST","PAYMENT_FEE","DIRECT_MARKETING_COST","APPROVED_DIRECT_OTHER_COST","APPROVED_SHARED_CENTRAL_COST"],"vat_treatment":"EXCLUDED_FROM_REVENUE_AND_PROFIT","shared_central_cost_policy":"EXCLUDED_UNLESS_EXPLICITLY_APPROVED_AND_VERSIONED","rounding_policy":"LAST_BENEFICIARY_REMAINDER"}',private.canonical_request_hash('{"rule":"GOLD_MASTER_STANDARD_DEFAULT_V1"}'::jsonb),'2026-09-10','ACTIVE','Gold Master V4 FINAL — règle par défaut autres franchises 50/25/25')on conflict(franchise_type,version)do nothing;
